CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE CHECK (email = lower(email)), password_hash text NOT NULL, display_name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE patients (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), first_name text NOT NULL, last_name text NOT NULL, date_of_birth date, timezone text NOT NULL DEFAULT 'UTC', status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','archived')), home_address text, emergency_contact jsonb, created_by uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE family_patient_access (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT, patient_id uuid NOT NULL REFERENCES patients(id) ON DELETE RESTRICT, role text NOT NULL CHECK(role IN ('primary_caregiver','family_caregiver','read_only')), invited_by uuid REFERENCES users(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz, UNIQUE(user_id, patient_id));
CREATE TABLE known_people (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), patient_id uuid NOT NULL REFERENCES patients(id) ON DELETE RESTRICT, name text NOT NULL, relationship text NOT NULL, notes text, photo_key text, review_status text NOT NULL DEFAULT 'pending' CHECK(review_status IN ('pending','verified','rejected')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), archived_at timestamptz);
CREATE TABLE health_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), patient_id uuid NOT NULL REFERENCES patients(id) ON DELETE RESTRICT, title text NOT NULL, category text, record_date date, notes text, storage_key text NOT NULL, original_filename text NOT NULL, mime_type text NOT NULL, byte_size integer NOT NULL CHECK(byte_size >= 0), uploaded_by uuid REFERENCES users(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE TABLE smartwatch_devices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), patient_id uuid NOT NULL REFERENCES patients(id) ON DELETE RESTRICT, device_identifier text NOT NULL UNIQUE, label text NOT NULL, source text NOT NULL, status text NOT NULL DEFAULT 'inactive', last_synced_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE smartwatch_readings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), patient_id uuid NOT NULL REFERENCES patients(id) ON DELETE RESTRICT, device_id uuid REFERENCES smartwatch_devices(id) ON DELETE SET NULL, measurement_type text NOT NULL, value numeric NOT NULL, unit text NOT NULL, source text NOT NULL, recorded_at timestamptz NOT NULL, simulated boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE device_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), patient_id uuid NOT NULL REFERENCES patients(id) ON DELETE RESTRICT, device_id uuid REFERENCES smartwatch_devices(id) ON DELETE SET NULL, event_type text NOT NULL, details jsonb NOT NULL DEFAULT '{}', occurred_at timestamptz NOT NULL DEFAULT now(), simulated boolean NOT NULL DEFAULT false);
CREATE TABLE locations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), patient_id uuid NOT NULL REFERENCES patients(id) ON DELETE RESTRICT, latitude numeric NOT NULL CHECK(latitude BETWEEN -90 AND 90), longitude numeric NOT NULL CHECK(longitude BETWEEN -180 AND 180), source text NOT NULL, recorded_at timestamptz NOT NULL DEFAULT now(), simulated boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE routines (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), patient_id uuid NOT NULL REFERENCES patients(id) ON DELETE RESTRICT, title text NOT NULL, category text NOT NULL, recurrence text NOT NULL, reminder_time time, timezone text NOT NULL DEFAULT 'UTC', active boolean NOT NULL DEFAULT true, created_by uuid REFERENCES users(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE TABLE tasks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), patient_id uuid NOT NULL REFERENCES patients(id) ON DELETE RESTRICT, routine_id uuid REFERENCES routines(id) ON DELETE SET NULL, title text NOT NULL, due_at timestamptz NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','completed','skipped')), completed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE conversations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), patient_id uuid NOT NULL REFERENCES patients(id) ON DELETE RESTRICT, known_person_id uuid REFERENCES known_people(id) ON DELETE SET NULL, occurred_at timestamptz NOT NULL, summary text, location_id uuid REFERENCES locations(id) ON DELETE SET NULL, consent_recorded boolean NOT NULL DEFAULT false, deleted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE voice_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), conversation_id uuid NOT NULL REFERENCES conversations(id) ON DELETE RESTRICT, storage_key text NOT NULL, mime_type text NOT NULL, duration_seconds integer, created_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE TABLE transcripts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), conversation_id uuid NOT NULL REFERENCES conversations(id) ON DELETE RESTRICT, content text NOT NULL, processing_status text NOT NULL DEFAULT 'ready', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE daily_summaries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), patient_id uuid NOT NULL REFERENCES patients(id) ON DELETE RESTRICT, summary_date date NOT NULL, content text, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','ready','failed')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(patient_id, summary_date));
CREATE TABLE alerts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), patient_id uuid NOT NULL REFERENCES patients(id) ON DELETE RESTRICT, type text NOT NULL, severity text NOT NULL CHECK(severity IN ('low','medium','high','critical')), message text NOT NULL, status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','acknowledged','resolved')), assigned_user_id uuid REFERENCES users(id) ON DELETE SET NULL, acknowledged_at timestamptz, resolved_at timestamptz, resolution_notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE doctor_contacts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), patient_id uuid NOT NULL REFERENCES patients(id) ON DELETE RESTRICT, name text NOT NULL, specialty text, phone text NOT NULL, notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE TABLE notification_subscriptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT, patient_id uuid NOT NULL REFERENCES patients(id) ON DELETE RESTRICT, channel text NOT NULL, enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notification_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), patient_id uuid NOT NULL REFERENCES patients(id) ON DELETE RESTRICT, task_id uuid REFERENCES tasks(id) ON DELETE SET NULL, scheduled_for timestamptz NOT NULL, status text NOT NULL DEFAULT 'pending', dedupe_key text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE recognition_tests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), patient_id uuid NOT NULL REFERENCES patients(id) ON DELETE RESTRICT, known_person_id uuid REFERENCES known_people(id) ON DELETE SET NULL, expected_label text, actual_label text, outcome text NOT NULL, tested_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES users(id) ON DELETE SET NULL, patient_id uuid REFERENCES patients(id) ON DELETE SET NULL, action text NOT NULL, entity_type text NOT NULL, entity_id uuid, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX idx_access_user_patient ON family_patient_access(user_id, patient_id) WHERE revoked_at IS NULL;
CREATE INDEX idx_people_patient ON known_people(patient_id) WHERE archived_at IS NULL;
CREATE INDEX idx_tasks_patient_due ON tasks(patient_id, due_at DESC);
CREATE INDEX idx_readings_patient_time ON smartwatch_readings(patient_id, recorded_at DESC);
CREATE INDEX idx_locations_patient_time ON locations(patient_id, recorded_at DESC);
CREATE INDEX idx_alerts_patient_status ON alerts(patient_id, status, created_at DESC);
CREATE INDEX idx_conversations_patient_time ON conversations(patient_id, occurred_at DESC);
